"""Task-specific additions reviewed 30 October 2026; earlier mechanics stay scoped."""
def apply(pages):
 from azeroth_survivors_content import para,steps,table,ref,a,SOURCES
 SOURCES['deck_report']=('https://www.reddit.com/r/SteamDeck/comments/1xfk2fq/azeroth_survivors_on_steam_deck_video_guide/','Reddit · NastyGnar and replies','Read 30 October 2026. Author reports a Windows-build Steam Deck route; a reply reports failure to launch. Search and displayed relative dates disagree; exact post date unconfirmed. No device test by this site.')
 for d in pages:
  if d['slug'] in ['beginners-guide/','save-backup/','mobile/']:
   d['review_note']='Reviewed 30 October 2026 · Original v0.127.0 mechanics; v0.130.0 menu captures labelled separately · Source-based, not a playtest'
  if d['slug']=='beginners-guide/':
   d['parts'] += [
    ('controller','Controller settings: check input before a long run',para('Open Options → Gamepad. The original v0.130.0 menu inspected on 30 October 2026 shows camera inversion, camera speed, zoom speed and stick dead zone. Its on-screen hint maps the left stick to movement, right stick to the view, A to jump, bumpers/triggers to zoom and Y to stored level-ups. This is menu evidence, not a controller compatibility test.')+steps(['Confirm movement and camera input in a short attempt before importing your only save.','If the camera direction feels wrong, change the corresponding inversion setting.','If the stick drifts, adjust the dead zone and check again; do not assume the displayed default suits every controller.','Keep a keyboard or other working input available until you have checked menus and upgrade selection.'])+para('A Steam Deck report does not establish that every controller or browser exposes the same inputs. '+a('mobile/#steam-deck','Read the Steam Deck evidence boundary'))),
    ('gear-upgrades','Gear will not upgrade: marks, stars or the wrong item?',para('For permanent gear, open the Armory from the hero picker, choose the class and inspect the piece in Collection. Use the piece’s displayed Upgrade control and cost rather than a price from another class or version. The following decision order is based on original v0.127.0 interface text inspected 29 October 2026; it has not been replayed in v0.130.0. '+ref('game'))+table(['What you see','What to check next'],[['Nothing worn adds bonuses','Find class gear from the bosses shown for the piece; starting clothes are not upgraded boss gear.'],['LOOK rather than equipped gear','Right-click equips/unequips; Shift+Right-click chooses the appearance. A look alone adds no gear bonus.'],['Not enough marks','Compare that class’s marks with the cost displayed on this piece. Do not substitute gold or a cost from another item.'],['Stars locked','Read the required Heroic level and zones on the piece. The text directs a first unlock to Heroic I in its zones; marks alone do not bypass that condition.'],['Fully upgraded','Choose another piece or improve another constraint; this is not a failed payment.']])+para('Make one change, then inspect the worn piece and bonuses before spending more. Four pieces of one set require at least one star each for its four-piece bonus; the eight-piece bonus requires all eight at three stars or above in this inspected version. This is a progression check, not a best-in-slot or farming-rate claim. '+ref('game')))]
  if d['slug']=='save-backup/':
   d['parts'].insert(0,('location','Where is the browser save?',para('Browser progress belongs to the game address and browser profile; it is not automatically a portable file in Downloads. Use Options → Saves → Export Save to create the .sav file you can move. Its download location depends on your browser’s download settings. '+ref('saves'))+para('The original launcher inspected 29 October reads the browser localStorage key <code>rogue.characters</code>, then <code>rogue.characters.backup.1</code> as a fallback when offering “Download your save”. This describes that browser launcher, not a Windows desktop save-folder path. This implementation detail is scoped to the launcher inspected on 29 October 2026. '+ref('launcher'))+steps(['Return to the same original host, browser and profile first.','If the game opens, export through its Saves menu. If a launcher recovery download is offered, preserve that file unchanged.','If neither is available, keep the old profile intact while looking for an earlier exported file. Do not clear site data as a recovery step.','Back up the destination separately before importing; inspect the resulting heroes and equipment.'])+para('No cloud synchronization, recovery from erased storage or desktop directory is verified here.')))
  if d['slug']=='mobile/':
   d['parts'].insert(1,('steam-deck','Steam Deck: separate a player report from a verified setup',para('A Reddit post by NastyGnar describes using the Windows build on Steam Deck; another participant says it does not launch. We read the thread on 30 October 2026, but its indexed date and displayed relative date differ. We have not watched and reproduced the complete installation video, selected a Proton version or completed a Deck run. '+ref('deck_report'))+table(['Your goal','Supported next step','Still unverified'],[['Get the original Windows archive','Use the Windows link on Aethus’s original page, then preserve your export before changing clients. '+ref('launcher'),'A universal Proton configuration or performance target.'],['Use a controller','Check the original Gamepad menu and test movement, camera and upgrades. '+a('beginners-guide/#controller','See the inspected controls'),'Every browser/controller mapping and physical Deck behaviour.'],['Move progress','Export both source and destination before import. '+a('save-backup/','Use the backup order'),'Automatic browser-to-desktop synchronization.']])+para('The GitHub reconstruction is a separate client; a successful installation of it does not validate the current original Windows build. Ask for the exact host, build, launch error and compatibility-layer version when comparing reports. '+ref('rebuild'))))
  if d['slug']=='beginners-guide/':
   d['parts']=[(i,t,body+('<figure><img src="/assets/azeroth-survivors/images/az-gamepad-1280.webp" width="1280" height="889" loading="lazy" alt="Original Gamepad menu with inversion, speed and stick dead zone controls"><figcaption>Aethus original browser game v0.130.0 / e7d9dd47, captured 30 October 2026. Menu inspection only; no physical controller test. '+ref('game')+'</figcaption></figure>' if i=='controller' else '')) for i,t,body in d['parts']]
 return pages

